"""Export the canonical Python fixtures for the dependency-free static frontend."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from demo_scenarios import DEMO_SCENARIOS


def render() -> str:
    data = json.dumps(DEMO_SCENARIOS, indent=2, ensure_ascii=True)
    return (
        "// Generated by scripts/export_demo_scenarios.py; edit demo_scenarios.py.\n"
        f"window.DRIFTGUARD_SCENARIOS = {data};\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail when fixtures are stale.")
    args = parser.parse_args()
    target = ROOT / "site" / "scenarios.js"
    expected = render()
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != expected:
            print("Frontend fixtures are stale. Run python3 scripts/export_demo_scenarios.py.")
            return 1
    else:
        target.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
